async function main(helpers) {
  function env(name, fallback = '') {
    let value = '';
    try { value = $env[name] || ''; } catch (error) {}
    try { value = value || $vars?.[name] || ''; } catch (error) {}
    return value || fallback;
  }

  function required(value, label) {
    if (value === undefined || value === null || String(value).trim() === '') throw new Error(label + ' obrigatorio');
    return String(value).trim();
  }

  async function supabaseRequest(method, path, body, prefer = '') {
    const baseUrl = required(env('SUPABASE_URL'), 'SUPABASE_URL').replace(/\/$/, '');
    const serviceKey = required(env('SUPABASE_SERVICE_ROLE_KEY'), 'SUPABASE_SERVICE_ROLE_KEY');
    const headers = { 'Content-Type': 'application/json', apikey: serviceKey, Authorization: 'Bearer ' + serviceKey };
    if (prefer) headers.Prefer = prefer;
    return helpers.httpRequest({ method, url: baseUrl + path, headers, body, json: true });
  }

  function normalize(value) {
    return String(value || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  }

  function hasAny(text, values) {
    return values.some((value) => text.includes(value));
  }

  function classify(text) {
    const normalized = normalize(text);
    let service = 'geral';
    let stage = 'Qualificacao';
    let handoff = false;
    if (hasAny(normalized, ['orcamento', 'proposta', 'contrato', 'quanto custa', 'preco', 'valor'])) {
      service = 'comercial';
      stage = 'Orcamento solicitado';
      handoff = true;
    } else if (hasAny(normalized, ['urgente', 'fora do ar', 'parado', 'caiu', 'nao funciona', 'erro'])) {
      service = 'suporte_ti';
      stage = 'Suporte tecnico';
      handoff = true;
    } else if (hasAny(normalized, ['sistema', 'software', 'app', 'site', 'dashboard', 'api', 'integracao', 'automacao'])) {
      service = 'software_automacao';
      stage = 'Briefing necessario';
    } else if (hasAny(normalized, ['trafego', 'anuncio', 'google ads', 'meta ads', 'campanha', 'leads'])) {
      service = 'trafego_pago';
      stage = 'Briefing necessario';
    } else if (hasAny(normalized, ['social media', 'instagram', 'conteudo', 'post', 'reels', 'criativo'])) {
      service = 'social_media';
      stage = 'Briefing necessario';
    } else if (hasAny(normalized, ['humano', 'atendente', 'especialista', 'ligar', 'pessoa'])) {
      service = 'atendimento_humano';
      stage = 'Atendimento humano';
      handoff = true;
    } else if (hasAny(normalized, ['agendar', 'agenda', 'reuniao', 'horario', 'visita'])) {
      service = 'agendamento';
      stage = 'Agendamento';
    }
    return { service, stage, handoff };
  }

  function answer(text, classification, name) {
    const normalized = normalize(text);
    if (!text || hasAny(normalized, ['oi', 'ola', 'bom dia', 'boa tarde', 'boa noite', 'menu', 'teste'])) {
      return 'Ola, ' + name + '! Sou o atendimento da JIW - Solucoes tecnologicas. Posso ajudar com software, sites, automacoes, suporte de TI, trafego pago, social media ou consultoria digital. O que sua empresa precisa?';
    }
    if (classification.handoff) return 'Certo. Vou encaminhar seu atendimento para um especialista da JIW. Envie seu nome, empresa, objetivo e melhor contato. [HUMANO_SOLICITADO]';
    if (classification.stage === 'Agendamento') return 'Para agendar, envie o servico desejado, melhor dia e horario e um telefone para confirmacao.';
    if (classification.service === 'software_automacao') return 'A JIW pode ajudar com sistemas, sites, dashboards, integracoes e automacoes. Qual problema voce quer resolver e o que ja existe hoje?';
    if (classification.service === 'suporte_ti') return 'Descreva o equipamento ou sistema com problema, o impacto para a equipe e se existe urgencia.';
    if (classification.service === 'trafego_pago') return 'Para avaliar trafego pago, diga o que sua empresa vende, regiao de atendimento e objetivo principal: leads, vendas ou agenda.';
    if (classification.service === 'social_media') return 'Para direcionar social media, diga o segmento da empresa, redes usadas e se precisa de estrategia, criacao ou gestao.';
    return 'Para eu direcionar melhor, sua necessidade esta ligada a software/site/automacao, suporte de TI, trafego pago, social media ou consultoria digital?';
  }

  const input = typeof $json.body === 'string' ? JSON.parse($json.body || '{}') : ($json.body || $json);
  const eventName = normalize(input.event || input.type || '');
  const acceptedEvents = ['messages.upsert', 'messages.update'];
  if (eventName && !acceptedEvents.includes(eventName)) return { ok: true, ignored: true, reason: 'event_not_supported', event: eventName };

  const data = input.data || input;
  const key = data.key || data.message?.key || {};
  if (Boolean(key.fromMe || data.fromMe)) return { ok: true, ignored: true, reason: 'outbound_event' };

  const remoteJid = key.remoteJid || key.remoteJidAlt || data.remoteJid || '';
  if (!remoteJid || remoteJid.includes('@g.us') || remoteJid === 'status@broadcast') return { ok: true, ignored: true, reason: 'group_or_status' };
  const phone = remoteJid.split('@')[0].split(':')[0].replace(/\D/g, '');
  if (!phone) return { ok: true, ignored: true, reason: 'missing_phone' };

  const message = data.message || {};
  const messageType = data.messageType || Object.keys(message)[0] || 'conversation';
  let messageText = message.conversation || message.extendedTextMessage?.text || message.imageMessage?.caption || message.videoMessage?.caption || message.documentMessage?.caption || '';
  let contentType = 'text';
  if (!messageText) {
    contentType = messageType.replace('Message', '').toLowerCase() || 'unknown';
    messageText = '[' + contentType + ']';
  }

  const messageId = String(key.id || data.id || remoteJid + ':' + Date.now());
  const tenantSlug = env('WHATSAPP_TENANT_SLUG', 'jiw').toLowerCase();
  const instance = input.instance || input.instanceName || env('EVOLUTION_INSTANCE_JIW', '');
  const contactName = data.pushName || data.senderName || phone;
  const duplicatePath = '/rest/v1/channel_events?tenant_slug=eq.' + encodeURIComponent(tenantSlug) + '&channel_type=eq.whatsapp&external_message_id=eq.' + encodeURIComponent(messageId) + '&select=id';
  const existing = await supabaseRequest('GET', duplicatePath);
  if (Array.isArray(existing) && existing.length) return { ok: true, duplicate: true, external_message_id: messageId };

  const classification = classify(messageText);
  const responseText = answer(messageText, classification, contactName).replace('[HUMANO_SOLICITADO]', '').trim();
  const handoff = classification.handoff || answer(messageText, classification, contactName).includes('[HUMANO_SOLICITADO]');
  const inboundEvent = {
    tenant_slug: tenantSlug,
    channel_type: 'whatsapp',
    external_conversation_id: remoteJid,
    external_message_id: messageId,
    direction: 'inbound',
    sender_type: 'contact',
    contact_name: contactName,
    contact_handle: phone,
    message_text: messageText,
    service: classification.service,
    stage: classification.stage,
    handoff,
    response_text: responseText,
    delivery_status: 'received',
    raw_payload: input
  };
  await supabaseRequest('POST', '/rest/v1/channel_events', inboundEvent, 'return=representation,resolution=ignore-duplicates');

  let sent = null;
  let deliveryStatus = 'disabled';
  if (String(env('WHATSAPP_AUTOREPLY', 'true')).toLowerCase() === 'true' && instance) {
    const evolutionUrl = required(env('EVOLUTION_API_URL'), 'EVOLUTION_API_URL').replace(/\/$/, '');
    const apiKey = required(env('EVOLUTION_API_KEY'), 'EVOLUTION_API_KEY');
    sent = await helpers.httpRequest({
      method: 'POST',
      url: evolutionUrl + '/message/sendText/' + encodeURIComponent(instance),
      headers: { 'Content-Type': 'application/json', apikey: apiKey },
      body: { number: phone, text: responseText },
      json: true
    });
    deliveryStatus = 'sent';
    const outboundId = String(sent?.key?.id || sent?.message?.key?.id || sent?.id || messageId + ':reply');
    await supabaseRequest('POST', '/rest/v1/channel_events', {
      tenant_slug: tenantSlug,
      channel_type: 'whatsapp',
      external_conversation_id: remoteJid,
      external_message_id: outboundId,
      direction: 'outbound',
      sender_type: 'assistant',
      contact_name: contactName,
      contact_handle: phone,
      message_text: responseText,
      service: classification.service,
      stage: classification.stage,
      handoff,
      delivery_status: deliveryStatus,
      raw_payload: { provider: 'evolution_api', response: sent }
    }, 'return=representation,resolution=ignore-duplicates');
  }

  return { ok: true, tenant_slug: tenantSlug, channel_type: 'whatsapp', instance, external_conversation_id: remoteJid, external_message_id: messageId, message_text: messageText, response_text: responseText, service: classification.service, stage: classification.stage, handoff, content_type: contentType, delivery_status: deliveryStatus, sent };
}

try { return { json: await main(this.helpers) }; } catch (error) { return { json: { ok: false, error: error.message || String(error) } }; }
